def comps(g):
 h,w=len(g),len(g[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   if g[r][c] and (r,c) not in seen:
    col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
    while stack:
     x,y=stack.pop(); cells.append((x,y))
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      a,b=x+dx,y+dy
      if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==col:
       seen.add((a,b)); stack.append((a,b))
    objs.append((col,cells))
 return objs

